const repos = $input.first().json.repos ?? [];
const since = new Date(Date.now() - 150000).toISOString();
return repos
  .filter(r => r.platform === 'github' && r.remote_id && r.remote_id.includes('/'))
  .map(r => {
    const [owner, repo] = r.remote_id.split('/');
    return { json: { owner, repo, name: r.name, since } };
  });

// Normalize GitHub item, conversation and review activity.
// PR details supply participant data but do not produce separate events.

const items = $input.all();
const since = Date.parse($('Build Repo Items').first().json.since);
const reviewEventTypes = {
  APPROVED: 'pull_request_review_approved',
  CHANGES_REQUESTED: 'pull_request_review_changes_requested'
};

// 0. Separate PR detail items (from Pulls API) for reviewer lookup.
// Items from the Pulls API have requested_reviewers + base.repo; regular
// issues/comments from the Issues API do not.
const prDetailMap = {};
const regularItems = [];
for (const item of items) {
  const d = item.json;
  if (d.requested_reviewers !== undefined && d.base && d.base.repo) {
    const baseUrl = d.base.repo.url || '';
    const rm = baseUrl.match(/repos\/([^\/]+)\/([^\/]+)$/);
    if (rm && d.number) {
      const key = rm[1] + '/' + rm[2] + '/' + d.number;
      prDetailMap[key] = {
        title: d.title || '',
        mergedAt: d.merged_at,
        hasAssignees: Array.isArray(d.assignees),
        hasReviewers: Array.isArray(d.requested_reviewers),
        author: { role: 'author', name: (d.user && d.user.login) || '', handle: (d.user && d.user.login) || '' },
        reviewers: (d.requested_reviewers || []).map(function(r) {
          return { role: 'reviewer', name: r.login || '', handle: r.login || '' };
        }),
        assignees: (d.assignees || []).map(function(a) {
          return { role: 'assignee', name: a.login || '', handle: a.login || '' };
        })
      };
    }
  } else {
    regularItems.push(item);
  }
}

// 1. Classify regular items: comments have 'issue_url', issues have 'repository_url'
const rawIssues = [];
const rawComments = [];
const reviewActivity = [];
const reviewActivityTimes = new Map();
for (const item of regularItems) {
  const d = item.json;
  if (d.issue_url) {
    rawComments.push(d);
  } else if (d.pull_request_url) {
    const match = d.pull_request_url.match(/repos\/([^/]+)\/([^/]+)\/pulls\/(\d+)$/);
    if (!match || !d.id) continue;
    const [, owner, repo, number] = match;
    const key = owner + '/' + repo + '/' + number;
    const inline = d.pull_request_review_id !== undefined;
    const rawType = inline ? 'issue_comment_created' : reviewEventTypes[d.state];
    const timestamp = inline ? d.created_at : d.submitted_at;
    const activityTime = Date.parse(timestamp);
    if (!rawType || !Number.isFinite(activityTime) || (!inline && activityTime < since)) continue;

    reviewActivity.push({key, owner, repo, number, record: d, inline, rawType, timestamp});
    const times = reviewActivityTimes.get(key) || new Set();
    times.add(Date.parse(inline ? d.updated_at || timestamp : timestamp));
    reviewActivityTimes.set(key, times);
  } else if (d.repository_url || d.number !== undefined) {
    rawIssues.push(d);
  }
}

// 2. Build a set of "owner/repo/issueNumber" keys that have recent comments
const commentedIssueKeys = new Set();
for (const comment of rawComments) {
  const m = (comment.issue_url || '').match(/repos\/([^\/]+)\/([^\/]+)\/issues\/(\d+)$/);
  if (m) commentedIssueKeys.add(m[1] + '/' + m[2] + '/' + m[3]);
}

// 3. Normalize issues — skip those that only got bumped by a comment
const allEvents = [];
const issuesByKey = new Map();
for (const issue of rawIssues) {
  const repoUrl = issue.repository_url || '';
  const rm = repoUrl.match(/repos\/([^\/]+)\/([^\/]+)$/);
  const owner = rm ? rm[1] : 'unknown';
  const repo = rm ? rm[2] : 'unknown';
  const key = owner + '/' + repo + '/' + issue.number;

  issuesByKey.set(key, issue);
  const isPR = !!issue.pull_request;

  const updatedAt = issue.updated_at || new Date().toISOString();
  const activities = [];
  if (isPR) {
    const mergedAt = issue.pull_request.merged_at || prDetailMap[key]?.mergedAt;
    const closedAt = issue.state === 'closed' ? mergedAt || issue.closed_at : undefined;
    const closedEpoch = Date.parse(closedAt);
    const updatedEpoch = Date.parse(updatedAt);

    // A closure's identity comes from the transition, even if later PR updates overlap it.
    if (closedEpoch >= since) {
      activities.push({
        timestamp: closedAt, type: 'pull_request_closed', mergedAt,
        prefix: (mergedAt ? 'evt_github_pr_merged_' : 'evt_github_pr_closed_') + $workflow.id + '_'
      });
    }

    const matchesReview = issue.created_at !== issue.updated_at
      && reviewActivityTimes.get(key)?.has(updatedEpoch);
    if (updatedEpoch >= since && (!closedAt || updatedEpoch > closedEpoch)
        && !commentedIssueKeys.has(key) && !matchesReview) {
      activities.push({timestamp: updatedAt, type: 'pull_request_updated', prefix: 'evt_github_pr_'});
    }
  } else if (!commentedIssueKeys.has(key)) {
    const type = issue.state === 'closed' ? 'issue_closed' : 'issue_updated';
    activities.push({timestamp: updatedAt, type, prefix: 'evt_github_issue_'});
  }

  if (!activities.length) continue;

  // Build participants list
  const participants = [
    { role: 'author', name: (issue.user && issue.user.login) || '', handle: (issue.user && issue.user.login) || '' },
    ...(issue.assignees || []).map(function(a) { return { role: 'assignee', name: a.login || '', handle: a.login || '' }; })
  ];

  // For PRs, merge reviewers from the Pulls API if available
  if (isPR) {
    const prDetail = prDetailMap[key];
    if (prDetail) {
      const existingHandles = new Set(participants.map(function(p) { return p.handle; }));
      for (const r of prDetail.reviewers) {
        if (r.handle && !existingHandles.has(r.handle)) {
          participants.push(r);
          existingHandles.add(r.handle);
        }
      }
    }
  }

  for (const {timestamp, type, prefix, mergedAt} of activities) {
    allEvents.push({
      json: {
        event_id: prefix + owner + '_' + repo + '_' + issue.number + '_' + Date.parse(timestamp),
        timestamp,
        source: {
          platform: 'github',
          connection_id: $workflow.id,
          raw_event_type: type
        },
        actor: {
          name: (issue.user && issue.user.login) || 'unknown',
          email: '',
          platform_handle: (issue.user && issue.user.login) || ''
        },
        subject: {
          type: isPR ? 'pull_request' : 'ticket',
          id: owner + '/' + repo + '/' + issue.number,
          title: issue.title || '',
          url: issue.html_url || ''
        },
        content: {
          body: issue.body || '',
          attachments: [],
          metadata: {
            state: issue.state,
            merged_at: mergedAt,
            labels: (issue.labels || []).map(function(l) { return l.name; }),
            repo: owner + '/' + repo,
            is_pr: isPR,
            participants: participants
          }
        }
      }
    });
  }
}

// 4. Normalize comments — always emitted
for (const comment of rawComments) {
  if (!comment.id) continue;
  const m = (comment.issue_url || '').match(/repos\/([^\/]+)\/([^\/]+)\/issues\/(\d+)$/);
  if (!m) continue;
  const owner = m[1];
  const repo = m[2];
  const issueNumber = m[3];
  const htmlUrl = comment.html_url || '';
  const issueHtmlUrl = htmlUrl.replace(/#issuecomment-.*$/, '');
  const epoch = new Date(comment.created_at || Date.now()).getTime();

  // Check if this comment is on a PR (has entry in prDetailMap)
  const prKey = owner + '/' + repo + '/' + issueNumber;
  const prDetail = prDetailMap[prKey];

  let participants;
  let subjectType = 'ticket';
  let subjectTitle = 'Issue #' + issueNumber;
  if (prDetail) {
    // Comment is on a PR — include full PR participant list for role resolution
    subjectType = 'pull_request';
    subjectTitle = prDetail.title || ('PR #' + issueNumber);
    const parts = [prDetail.author];
    const existingHandles = new Set([prDetail.author.handle]);
    for (const a of prDetail.assignees) {
      if (a.handle && !existingHandles.has(a.handle)) {
        parts.push(a);
        existingHandles.add(a.handle);
      }
    }
    for (const r of prDetail.reviewers) {
      if (r.handle && !existingHandles.has(r.handle)) {
        parts.push(r);
        existingHandles.add(r.handle);
      }
    }
    // Add commenter if not already in the participant list
    const commenterHandle = (comment.user && comment.user.login) || '';
    if (commenterHandle && !existingHandles.has(commenterHandle)) {
      parts.push({ role: 'commenter', name: commenterHandle, handle: commenterHandle });
    }
    participants = parts;
  } else {
    participants = [
      { role: 'commenter', name: (comment.user && comment.user.login) || '', handle: (comment.user && comment.user.login) || '' }
    ];
  }

  allEvents.push({
    json: {
      event_id: 'evt_github_comment_' + owner + '_' + repo + '_' + comment.id + '_' + epoch,
      timestamp: comment.created_at || new Date().toISOString(),
      source: {
        platform: 'github',
        connection_id: $workflow.id,
        raw_event_type: 'issue_comment_created'
      },
      actor: {
        name: (comment.user && comment.user.login) || 'unknown',
        email: '',
        platform_handle: (comment.user && comment.user.login) || ''
      },
      subject: {
        type: subjectType,
        id: owner + '/' + repo + '/' + issueNumber,
        title: subjectTitle,
        url: issueHtmlUrl
      },
      content: {
        body: comment.body || '',
        attachments: [],
        metadata: {
          repo: owner + '/' + repo,
          issue_number: parseInt(issueNumber, 10),
          comment_id: comment.id,
          comment_url: htmlUrl,
          is_comment: true,
          participants: participants
        }
      }
    }
  });
}

// Review events belong to the PR entity but link directly to the submitted
// review or inline thread. A review's author is the actor, not the PR author.
for (const {key, owner, repo, number, record, inline, rawType, timestamp} of reviewActivity) {
  const pr = prDetailMap[key];
  const issue = issuesByKey.get(key);
  const author = pr?.author.handle || issue?.user?.login || '';
  const actor = record.user?.login || '';
  const assignees = pr?.assignees || (issue?.assignees || []).map(a => ({
    role: 'assignee', name: a.login, handle: a.login
  }));
  const participants = [
    {role: 'author', name: author, handle: author},
    ...assignees,
    ...(pr?.reviewers || []),
    ...(inline ? [{role: 'commenter', name: actor, handle: actor}] : [])
  ].filter(p => p.handle);
  const url = record.html_url || 'https://github.com/' + owner + '/' + repo + '/pull/' + number;

  allEvents.push({json: {
    event_id: 'evt_github_' + (inline ? 'review_comment_' : 'review_')
      + $workflow.id + '_' + owner + '_' + repo + '_' + record.id,
    timestamp,
    source: {
      platform: 'github',
      connection_id: $workflow.id,
      raw_event_type: rawType
    },
    actor: {name: actor || 'unknown', email: '', platform_handle: actor},
    subject: {
      type: 'pull_request',
      id: key,
      title: pr?.title || issue?.title || 'PR #' + number,
      url
    },
    content: {
      body: record.body || '',
      attachments: [],
      metadata: {
        repo: owner + '/' + repo,
        issue_number: Number(number),
        is_pr: true,
        review_id: inline ? record.pull_request_review_id : record.id,
        item_participants_complete: Boolean(author && pr?.hasAssignees && pr?.hasReviewers),
        participants,
        ...(inline ? {
          is_comment: true,
          comment_kind: 'pull_request_review',
          comment_id: record.id,
          comment_url: url,
          path: record.path,
          line: record.line,
          original_line: record.original_line,
          side: record.side,
          diff_hunk: record.diff_hunk,
          in_reply_to_id: record.in_reply_to_id
        } : {
          review_state: record.state,
          review_url: url,
          commit_id: record.commit_id
        })
      }
    }
  }});
}

return allEvents;

// Runs on the error output of the three GitHub request nodes (onError:
// continueErrorOutput). Each failed item keeps its input fields (owner, repo)
// plus n8n's `error`. Before this, one 404/401/403 on any repo aborted the whole
// poll and no repo got ingested; now the good repos still flow through the
// success output, and each failure is reported to the engine's
// /ingestion-errors endpoint (same schema as the Laya error handler workflow) so
// it shows up in Audit with a per-repo message instead of being dropped.
// The engine coalesces repeats by (workflow, node, message) so a broken token
// polling every 2 minutes stays one row with a climbing occurrence count.

// With a credential attached, n8n hands the Code node a NodeApiError whose
// numeric code is not serialized: only its canned `message` (keyed by status
// in n8n's STATUS_CODE_MESSAGES) and `description` (GitHub's own message,
// e.g. "Bad credentials") survive. Try the numeric fields first, then map the
// canned message back to a status.
const MESSAGE_TO_STATUS = [
  ['Authorization failed', 401],
  ['Forbidden', 403],
  ['could not be found', 404],
  ['too many requests', 429],
  ['spacing your requests', 429],
];
function statusOf(err) {
  const direct = Number(err.httpCode ?? err.status ?? err.statusCode);
  if (Number.isFinite(direct) && direct > 0) return direct;
  const msg = String(err.message || '');
  for (const [needle, status] of MESSAGE_TO_STATUS) {
    if (msg.includes(needle)) return status;
  }
  return null;
}

const node = $prevNode.name;
return $input.all().map(item => {
  const d = item.json || {};
  const err = d.error || {};
  const repo = (d.owner && d.repo) ? d.owner + '/' + d.repo : 'unknown repo';
  const status = statusOf(err);
  const hint = status === 401 ? 'token invalid or revoked'
    : status === 403 ? 'token lacks access to this repo, or rate limited'
    : status === 404 ? 'repo not found, or not accessible with this token'
    : status === 429 ? 'rate limited'
    : 'request failed';
  const detail = err.description || err.message || '';
  return { json: {
    workflow_id: $workflow.id,
    workflow_name: $workflow.name,
    platform: 'github',
    node_name: node,
    node_type: 'n8n-nodes-base.httpRequest',
    error_name: err.name || 'GitHubRequestError',
    error_message: 'GitHub ' + (status || 'error') + ' for ' + repo + ': ' + hint
      + (detail ? ' (' + detail + ')' : ''),
    error_http_code: status,
    error_details: { repo, status, message: err.message, description: err.description },
    execution_id: String($execution.id || ''),
    execution_mode: $execution.mode || '',
    occurred_at: new Date().toISOString()
  } };
});

// The Pulls API is ordered by update time and paged through this poll's window.
// Reviews have their own submission time, checked after fetching their pages.
const items = $input.all();
const since = Date.parse($('Build Repo Items').first().json.since);
const pullUrls = new Set();
const requests = new Map();

function pullRequest(url) {
  const match = (url || '').match(/^https:\/\/api\.github\.com\/repos\/([^/]+)\/([^/]+)\/pulls\/(\d+)$/i);
  return match && {owner: match[1], repo: match[2], number: match[3]};
}

for (const {json: pull} of items) {
  if (!pull.base?.repo || pull.requested_reviewers === undefined) continue;
  const pr = pullRequest(pull.url);
  if (!pr) continue;
  const key = pull.url.toLowerCase();
  pullUrls.add(key);
  if (Date.parse(pull.updated_at) >= since) requests.set(key, {...pr, suffix: '/reviews'});
}

// An inline comment can be on a PR outside the list used for enrichment.
for (const {json: comment} of items) {
  if (comment.pull_request_review_id === undefined) continue;
  const pr = pullRequest(comment.pull_request_url);
  if (!pr) continue;
  const key = comment.pull_request_url.toLowerCase();
  if (!pullUrls.has(key)) requests.set(key, {...pr, suffix: ''});
}

return Array.from(requests.values(), json => ({json}));
